#!/usr/bin/env python3
"""Bake CRM customer detail mobile LTR scroll + 2-line Info wrap into app/index.html.

Idempotent. Edits ONLY the Info+Invoices grid inside renderCustomerDetail.
"""
from pathlib import Path

INDEX = Path('app/index.html')

OLD = '  <div style="display:grid;grid-template-columns:1fr 1.5fr;gap:16px">\n    <div class="card">\n      <div class="card-header"><div class="card-title">${APP.language===\'bm\'?\'Maklumat\':\'Info\'}</div></div>\n      <div style="padding:16px;display:flex;flex-direction:column;gap:12px">\n        ${[\n          [\'ti-mail\', cust.email],\n          [\'ti-phone\', cust.phone],\n          [\'ti-map-pin\', [cust.address_line1, cust.city, cust.postcode, cust.state].filter(Boolean).join(\', \')],\n          [\'ti-note\', cust.notes]\n        ].filter(([,v])=>v).map(([icon,val])=>`\n          <div style="display:flex;gap:10px;align-items:flex-start">\n            <i class="ti ${icon}" style="color:var(--text-3);margin-top:2px;flex-shrink:0"></i>\n            <span style="color:var(--text-2);font-size:13px">${val}</span>\n          </div>`).join(\'\')}\n        <div style="font-size:12px;color:var(--text-3);margin-top:4px">${t.created}: ${cust.created_at ? new Date(cust.created_at).toLocaleDateString(\'en-MY\') : \'-\'}</div>\n      </div>\n    </div>\n\n    <div class="card">\n      <div class="card-header"><div class="card-title">${t.invoices}</div><button class="btn btn-outline btn-sm" onclick="openPage(\'sales\')"><i class="ti ti-plus"></i></button></div>\n      ${(invs||[]).length === 0\n        ? `<div class="empty-state" style="padding:40px"><i class="ti ti-file-off"></i><p>${t.noInv}</p></div>`\n        : `<table><thead><tr><th>Ref</th><th>Date</th><th style="text-align:right">Total</th><th style="text-align:right">Paid</th><th style="text-align:right">Bal</th><th>Status</th></tr></thead><tbody>\n          ${(invs||[]).map(i=>{\n            const bal = Math.max(0, Number(i.total||0)-Number(i.paid_amt||0))\n            const st = String(i.status||\'\')\n            const badge = st===\'paid\'?\'badge-green\':st===\'partial\'?\'badge-yellow\':st===\'cancelled\'?\'badge-gray\':\'badge-red\'\n            return `<tr style="cursor:pointer" onclick="if(canAccess(\'sales\'))openPage(\'sales\',{view:\'inv-detail\',id:\'${i.id}\'});else showToast(APP.language===\'bm\'?\'Akses ditolak.\':\'Access denied.\',\'warning\')">\n            <td style="font-size:11px">${i.ref_no||\'-\'}</td>\n            <td style="font-size:12px">${i.issue_date ? new Date(i.issue_date).toLocaleDateString(\'en-MY\') : \'-\'}</td>\n            <td style="text-align:right">${formatRM(i.total)}</td>\n            <td style="text-align:right">${formatRM(i.paid_amt)}</td>\n            <td style="text-align:right">${formatRM(bal)}</td>\n            <td><span class="badge ${badge}">${st||\'-\'}</span></td>\n          </tr>`}).join(\'\')}\n          </tbody></table>`\n      }\n    </div>\n  </div>\n\n'

NEW = '  <div style="overflow-x:auto;-webkit-overflow-scrolling:touch;max-width:100%">\n  <div style="display:grid;grid-template-columns:minmax(280px,1fr) minmax(420px,1.5fr);gap:16px;min-width:700px">\n    <div class="card" style="min-width:0">\n      <div class="card-header"><div class="card-title">${APP.language===\'bm\'?\'Maklumat\':\'Info\'}</div></div>\n      <div style="padding:16px;display:flex;flex-direction:column;gap:12px">\n        ${[\n          [\'ti-mail\', cust.email],\n          [\'ti-phone\', cust.phone],\n          [\'ti-map-pin\', [cust.address_line1, cust.city, cust.postcode, cust.state].filter(Boolean).join(\', \')],\n          [\'ti-note\', cust.notes]\n        ].filter(([,v])=>v).map(([icon,val])=>`\n          <div style="display:flex;gap:10px;align-items:flex-start;min-width:0">\n            <i class="ti ${icon}" style="color:var(--text-3);margin-top:2px;flex-shrink:0"></i>\n            <span style="color:var(--text-2);font-size:13px;line-height:1.35;min-width:0;flex:1;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;word-break:normal;overflow-wrap:break-word">${val}</span>\n          </div>`).join(\'\')}\n        <div style="font-size:12px;color:var(--text-3);margin-top:4px">${t.created}: ${cust.created_at ? new Date(cust.created_at).toLocaleDateString(\'en-MY\') : \'-\'}</div>\n      </div>\n    </div>\n\n    <div class="card" style="min-width:0">\n      <div class="card-header"><div class="card-title">${t.invoices}</div><button class="btn btn-outline btn-sm" onclick="openPage(\'sales\')"><i class="ti ti-plus"></i></button></div>\n      ${(invs||[]).length === 0\n        ? `<div class="empty-state" style="padding:40px"><i class="ti ti-file-off"></i><p>${t.noInv}</p></div>`\n        : `<div style="overflow-x:auto;-webkit-overflow-scrolling:touch"><table style="width:max-content;min-width:100%"><thead><tr><th>Ref</th><th>Date</th><th style="text-align:right">Total</th><th style="text-align:right">Paid</th><th style="text-align:right">Bal</th><th>Status</th></tr></thead><tbody>\n          ${(invs||[]).map(i=>{\n            const bal = Math.max(0, Number(i.total||0)-Number(i.paid_amt||0))\n            const st = String(i.status||\'\')\n            const badge = st===\'paid\'?\'badge-green\':st===\'partial\'?\'badge-yellow\':st===\'cancelled\'?\'badge-gray\':\'badge-red\'\n            return `<tr style="cursor:pointer" onclick="if(canAccess(\'sales\'))openPage(\'sales\',{view:\'inv-detail\',id:\'${i.id}\'});else showToast(APP.language===\'bm\'?\'Akses ditolak.\':\'Access denied.\',\'warning\')">\n            <td style="font-size:11px">${i.ref_no||\'-\'}</td>\n            <td style="font-size:12px">${i.issue_date ? new Date(i.issue_date).toLocaleDateString(\'en-MY\') : \'-\'}</td>\n            <td style="text-align:right">${formatRM(i.total)}</td>\n            <td style="text-align:right">${formatRM(i.paid_amt)}</td>\n            <td style="text-align:right">${formatRM(bal)}</td>\n            <td><span class="badge ${badge}">${st||\'-\'}</span></td>\n          </tr>`}).join(\'\')}\n          </tbody></table></div>`\n      }\n    </div>\n  </div>\n  </div>\n\n'

def main():
    html = INDEX.read_text(encoding="utf-8")
    if NEW in html:
        print('already patched')
        return
    if OLD not in html:
        raise SystemExit('renderCustomerDetail Info+Invoices grid marker not found (already changed?)')
    html2 = html.replace(OLD, NEW, 1)
    if html2 == html:
        raise SystemExit('replace failed')
    INDEX.write_text(html2, encoding='utf-8')
    print('patched renderCustomerDetail Info+Invoices mobile LTR scroll')

if __name__ == '__main__':
    main()
